create table if not exists public.notification_delivery_claims (alert_event_id text not null, subscription_id text not null references public.push_subscriptions(subscription_id) on delete restrict, claim_status text not null check (claim_status in ('CLAIMED','SENT','FAILED')), attempt integer not null default 1 check (attempt > 0), claimed_at timestamptz not null default now(), claim_expires_at timestamptz not null, completed_at timestamptz, failure_code text, primary key (alert_event_id, subscription_id)); create index if not exists notification_delivery_claims_status_expiry_idx on public.notification_delivery_claims (claim_status, claim_expires_at); alter table public.notification_delivery_claims enable row level security; revoke all on table public.notification_delivery_claims from anon, authenticated;
